def solve(grid):
    """Count the number of islands (4-directionally connected 1s) in a binary grid.
    Args:
        grid (list[list[int]]): 2D grid of 0s and 1s.
    Returns:
        int: Number of islands.
    """
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    count = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 1 and not visited[i][j]:
                count += 1
                # BFS/DFS to mark the whole island
                stack = [(i, j)]
                visited[i][j] = True
                while stack:
