def solve(nums):
    n = len(nums)
    if n <= 1:
        return nums[:]
    # Find pivot
    i = n - 2
    while i >= 0 and nums[i] >= nums[i + 1]:
        i -= 1
    if i == -1:
        return sorted(nums)
    # Find rightmost successor to pivot
    j = n - 1
    while nums[j] <= nums[i]:
        j -= 1
    # Create copy and swap
    res = nums[:]
    res[i], res[j] = res[j], res[i]
    # Reverse suffix
    res[i+1:] = reversed(res[i+1:])
    return res

